steps.snippet:
el = device.find(description="New Event", class_name="ImageButton", clickable=True)
if el is None:
    el = device.find(description="New Event", clickable=True)
if el is None:
    raise RuntimeError("No 'New Event' button found on the calendar screen")
device.click(index=el)
device.settle(1.0)
if device.find(hint="Title", editable=True) is None:
    raise RuntimeError("New-event editor did not open after tapping 'New Event'")
